const makeResearch = (slug: string, title: string, excerpt: string, cluster: string, headlineStat: string, focus: string, relatedSlugs: readonly string[], published = '2026-08-07', sourceDate = august10ResearchSourceDates[slug] ?? published): ResearchPost => ({
  slug, title, excerpt, cluster, headlineStat, published, sourceDate, relatedSlugs, thumbnail: '/research-thumbnails/research-default.svg',
  sections: [
    { heading: 'Methodology', body: `This report compares ${researchSources.length} regulator, standards, and professional-body sources against one practical question: ${focus} We separate source requirements from operating recommendations and treat attorney or firm-manager review as the final decision gate.` },
    { heading: 'Key Stats', body: `${headlineStat} The source set contains ${researchSources.length} named references; the number is a coverage count for this report, not a claim about market performance. Validate local professional, privacy, and client-contract requirements before implementation.` },
    { heading: 'Key Takeaways', body: `Start with a narrow task definition, named owner, least-privilege access, a written exception path, and an auditable review sample. Offshore support can prepare and organize work, but it should not silently expand into legal advice, judgment, or client promises.` },
    { heading: 'Control design', body: `Write the input, output, system, deadline, reviewer, and stop rule for ${focus}. Use individual accounts, approved templates, and a small first-week sample. Record what was received, what was changed, what remains uncertain, and who approved the handoff.` },
    { heading: 'Evidence and handoff', body: `Keep source notes with the work product, preserve the original client instruction, and log exceptions in plain language. A manager should be able to reconstruct the handoff without relying on a private chat or an untracked spreadsheet.` },
    { heading: 'Questions for the firm', body: `Which facts may the support role enter? Which fields require attorney review? What happens when a source conflicts, a deadline is unclear, or a client asks for advice? Who can pause the queue and who confirms the next safe step?` },
    { heading: 'FAQs', body: `Can this work be outsourced? Usually, repeatable preparation and administration can be scoped for support when confidentiality, access, supervision, and review are explicit. Can the role make a legal decision? No; route judgment, advice, filing strategy, and exceptions to the designated firm owner.` },
  ], sources: researchSources,
});

const makeAugust13Research = (slug: string, title: string, excerpt: string, cluster: string, headlineStat: string, focus: string, evidence: string, limitation: string, relatedSlugs: readonly string[], published: string, sourceDate: string): ResearchPost => ({
  slug, title, excerpt, published, sourceDate, cluster, headlineStat, relatedSlugs, thumbnail: '/research-thumbnails/research-default.svg',
  sections: [
    { heading: 'Methodology', body: `This report examines ${focus} through a bounded review of the ABA communication guidance, NIST Cybersecurity Framework 2.0, NIST SP 800-207, FTC safeguards guidance, ICO accountability material, the ICO data-sharing code, SRA confidentiality standards, Law Society outsourcing guidance, CISA cloud guidance, OWASP logging guidance, and NIST incident-handling guidance. The sources address different jurisdictions and risk models, so this is a comparative analysis rather than a statement that one rule governs every firm. The unit of analysis is the support handoff: an instruction or record enters, a support worker performs a defined administrative action, and an authorized firm owner reviews the result. The analysis distinguishes controls that reduce exposure from controls that prove what happened. It also distinguishes a factual field check from a legal conclusion. That distinction matters when work is performed by an offshore support role: location does not transfer professional responsibility, and a well-designed record cannot substitute for counsel's judgment.` },
    { heading: 'Research question', body: `The central question is whether ${focus} can be made reviewable without expanding the support role into legal advice. The sources consistently point toward a sequence of identifiable responsibilities: the firm defines the permitted purpose; access is limited to that purpose; the worker receives an approved input; the action is recorded; uncertainty is visible; and a named reviewer decides what happens next. ${evidence} In practical terms, the question is not whether a checklist exists. It is whether the checklist captures enough context for an attorney or manager to distinguish a completed administrative action from an unresolved legal issue. A mature record therefore includes the source used, its date or version, the person responsible, the system touched, and the state of the handoff. Where a source is silent, the firm should label the resulting recommendation as a local operating choice rather than present it as a universal requirement.` },
    { heading: 'Findings', body: `Across the sources, three findings are especially relevant. First, minimum-necessary access is both a confidentiality measure and a quality measure: a narrower workspace reduces the number of irrelevant records that a worker might misfile, disclose, or misinterpret. Second, provenance is more useful than a bare completion mark. A reviewer needs to know which document, message, field, or system state supported the entry, and whether the source was current when it was used. Third, escalation should be triggered by uncertainty rather than hidden behind a productivity target. A missing identifier, conflicting date, ambiguous instruction, unexpected recipient, or request for advice is evidence that the handoff has changed category. The support worker can preserve the facts and pause; the authorized owner decides the legal or client-facing response. This pattern applies to ${focus}, but the exact fields should be tested against the firm's matter types, client instructions, and professional obligations.` },
    { heading: 'Evidence design', body: `A useful evidence record for ${focus} has five layers. The first identifies the matter or approved work item without collecting unrelated personal information. The second records the instruction, source location, and source date so that another person can reproduce the factual check. The third records the administrative action in neutral language, including what was not changed. The fourth records exceptions, uncertainty, and the moment the work was stopped or routed. The fifth records the reviewing owner and disposition. These layers support different questions: what was requested, what was available, what was done, what remains unknown, and who accepted the result. Security guidance also favors event records that are attributable, protected from casual alteration, and retained for a defined purpose. The evidence should therefore be proportionate; a support role should not create a second uncontrolled database containing more client information than the underlying matter requires.` },
    { heading: 'Operational interpretation', body: `For a Philippines-based legal support arrangement, the research supports a role brief with a narrow input boundary, named systems, approved task examples, and an explicit stop condition. The role may organize, compare against supplied criteria, enter approved facts, and prepare a handoff. It should not decide privilege, eligibility, strategy, materiality, legal sufficiency, or whether a client should be given advice. A firm-side owner should set the sample for early review using a defined period or cohort, such as the first 20 work items or a weekly sample of completed records. That sample is an observation method, not a promise about accuracy. Review notes should classify defects by type—missing source, wrong matter, stale date, unauthorized change, or unresolved judgment—so the firm can improve the scope without blaming the worker for a decision they were never authorized to make. The same evidence should support access review and incident reconstruction when necessary.` },
    { heading: 'What the evidence does not show', body: `${limitation} The comparative sources also do not establish that offshore support is inherently safe or unsafe. Risk depends on the information involved, the systems used, supervision, contractual controls, access administration, and the firm's own professional duties. A citation to a standards document is not proof that a particular implementation complies with every applicable law or client agreement. Nor does a completed record prove that the underlying source was accurate. A reviewer should test a defined cohort, record exceptions, and revisit the scope when the matter type, jurisdiction, system, or client instruction changes. The research therefore favors visible uncertainty and periodic review over a one-time certification. Firms should obtain jurisdiction-specific advice where cross-border transfer, regulated information, privilege, or client consent creates a question outside ordinary administrative support.` },
    { heading: 'A practical test', body: `A firm can test the proposed boundary with a small cohort measured over a stated period. Select representative work items, remove any information that the support role does not need, and give the worker the same approved criteria that the role would receive in ordinary work. The reviewer should then compare the source, the recorded action, the exception state, and the handoff against the written scope. Count categories rather than claiming a single success rate: wrong source, incomplete field, stale instruction, unauthorized change, missing escalation, and reviewer correction are different observations. Record the denominator and period so that later results remain comparable. If the sample reveals recurring ambiguity, revise the task definition or review gate before expanding access. If it reveals an isolated factual error, correct the record and preserve the correction history. This test produces local evidence without pretending that one cohort proves a universal performance result.` },
    { heading: 'Bounded conclusion', body: `The evidence supports a bounded conclusion: ${focus} is suitable for supervised administrative support when purpose, access, source provenance, stop rules, and owner review are explicit. The conclusion is narrower than “the work can be outsourced.” It says that a defined slice of the work can be prepared in a way that leaves legal judgment with the firm and gives a reviewer enough evidence to accept, correct, or escalate it. The strongest design measure is not speed; it is the ability to reconstruct a completed handoff for a specified matter, period, and source set. For LegalServicesOffshore.com readers, that means evaluating a role by its approved task boundary and review evidence rather than by a job title alone. A firm should start with a small, representative cohort, document what it learns, and expand only when the owner can explain both successful work and exceptions.` },
    { heading: 'Questions for a firm review', body: `Before assigning ${focus}, the firm should answer: Which fields may be read, entered, or changed? Which source controls when two records conflict? What exact event pauses the work? Who owns the review, and within what period? Which accounts and devices are permitted? How is a correction distinguished from a new version? What evidence is retained, for how long, and who may access it? How are client instructions and contractual restrictions reflected? What happens when the worker is asked for advice or a commitment? These questions convert broad guidance into a local decision record. They also give a firm a basis for comparing an offshore support arrangement with its existing internal process without publishing unsupported performance claims or exposing confidential matter details.` },
    { heading: 'FAQs', body: `Does this research give legal advice? No. It compares authoritative guidance and describes an administrative boundary for supervised support. Can an offshore support worker resolve an ambiguous legal issue? No; the worker can preserve the facts and route the issue to the designated firm owner. Is a completion mark enough? No; source, action, exception, and review evidence are needed. Should every firm use the same fields? No; fields should reflect the matter, jurisdiction, client instruction, and system. The firm remains responsible for determining its professional and regulatory requirements.` },
  ],
  sources: researchSources,
});

type August18ResearchBrief = { slug: string; title: string; excerpt: string; cluster: string; headlineStat: string; question: string; evidence: string; analysis: string; example: string; boundary: string; limitation: string; conclusion: string; relatedSlugs: readonly string[]; published?: string; sourceDate?: string; sourceUrls?: readonly string[] };
// August 18 route records bind published: '2026-08-18' and sourceDate: '2026-08-18' independently.
const makeAugust18Research = (b: August18ResearchBrief): ResearchPost => ({
  slug: b.slug, title: b.title, excerpt: b.excerpt, cluster: b.cluster, headlineStat: b.headlineStat, published: b.published ?? '2026-08-18', sourceDate: b.sourceDate ?? '2026-08-18', relatedSlugs: b.relatedSlugs, thumbnail: '/research-thumbnails/research-default.svg',
  sections: [
    { heading: 'Research question and scope', body: `${b.question} This report studies that question in the setting of a Philippines-based legal support role serving a law firm or legal operations team. The role is assumed to work from firm-approved instructions and systems, with an attorney or firm manager retaining responsibility for legal judgment and client-facing decisions. The study therefore asks what evidence a support handoff should contain, not whether a particular matter has a correct legal outcome. That distinction keeps the research useful across intake, document, records, and case-administration work while respecting the boundaries of professional responsibility. ${b.evidence}` },
    { heading: 'Methodology', body: `The analysis compares twelve public sources: ABA Formal Opinion 477R on protected client information, NIST Cybersecurity Framework 2.0, NIST SP 800-207 on zero trust, the FTC Safeguards Rule, HHS Security Rule material, ICO data-protection-by-design guidance, the ICO data-sharing code, SRA confidentiality standards, Law Society outsourcing guidance, CISA cloud guidance, OWASP logging guidance, and NIST incident-handling guidance. These sources were selected because they address confidentiality, access, outsourcing, accountability, event evidence, or incident response. They do not all apply to every firm or jurisdiction. Source statements are treated as facts; recommendations in this report are analysis. The unit of analysis is a bounded handoff: approved input, defined administrative action, recorded exception, and named review owner. ${b.analysis}` },
    { heading: 'What the evidence suggests', body: `${b.evidence} Across the source set, the most durable pattern is not a particular application or staffing model. It is a chain of accountability: the firm defines purpose and permitted action; access is limited to that purpose; the worker records the source and action; uncertainty is visible; and an authorized reviewer decides the next step. That chain matters for offshore legal support because a clean administrative record can show what was done without pretending that the worker resolved a legal issue. A completion mark by itself is weak evidence. A source identifier, version or received date, action note, exception state, and reviewer disposition give the record context. ${b.analysis}` },
    { heading: 'Niche operating example', body: `${b.example} In this example, the support worker should preserve the original instruction, work only in the approved matter or queue, and record neutral facts. If the input is missing, contradictory, stale, or asks for an opinion, the worker should stop at the defined boundary and route the question. The firm-side reviewer can then decide whether to correct the source, revise the task, seek client clarification, or make a legal determination. This is why the same support role may be suitable for preparation in one queue and unsuitable for an adjacent queue: the information, criteria, review owner, and consequences differ. A practical pilot should use representative work items and retain the denominator and review period, rather than relying on anecdotes.` },
    { heading: 'Control design implications', body: `For ${b.title.toLowerCase()}, a useful control record names the matter or work item, permitted systems, source used, action taken, unchanged fields, exception signal, and reviewer. Access should follow the task rather than the worker's curiosity: named accounts, least-privilege permissions, and a documented removal process are more testable than a general promise of confidentiality. The work queue should also distinguish “awaiting source,” “prepared for review,” “returned for correction,” and “escalated for judgment.” Those states make a handoff legible to a manager in another time zone. A small review sample can classify wrong-source, missing-field, stale-instruction, unauthorized-change, and judgment-boundary observations separately. That classification helps the firm refine scope without turning a local sample into a performance guarantee.` },
    { heading: 'Role boundary', body: `${b.boundary} The support role can organize supplied information, compare it against explicit criteria, preserve provenance, and prepare a review packet. It should not infer legal meaning from a fact pattern, choose strategy, decide privilege or responsiveness, advise a client, approve a filing, or silently alter an instruction because a different result appears convenient. The firm should put those prohibitions beside the allowed examples and define who can pause the queue. A boundary is operational only when the worker can recognize the trigger and the reviewer can see the preserved context. This is particularly important when a seemingly clerical field—such as a date, recipient, party name, or document label—could change the legal significance of the matter.` },
    { heading: 'Limitations and evidence gaps', body: `${b.limitation} The sources also do not prove that offshore support is inherently safe or unsafe. They describe principles and obligations, while a firm's actual exposure depends on the matter, client agreement, systems, supervision, access administration, retention, and applicable law. A citation is not a compliance certification, and a completed checklist does not prove that its source was accurate. The comparative method cannot resolve jurisdiction-specific questions about transfer, privilege, consent, regulated data, or professional discipline. It also cannot predict a particular worker's performance from general control design. Local review, a defined sample, and periodic reassessment remain necessary when the matter type, system, client instruction, or scope changes.` },
    { heading: 'Evidence-led conclusion', body: `${b.conclusion} The defensible conclusion is narrower than “outsource this task.” It is that a well-scoped Philippines-based support role can make defined legal operations work more reviewable when the firm supplies approved inputs, limits access, preserves sources, records uncertainty, and retains the decision gate. The evidence favors visible provenance and escalation over silent completion. Before expanding a queue, the firm should test representative items, examine defects by category, confirm that prohibited decisions are not being performed, and reassess access and supervision. Those steps produce local evidence while leaving legal advice, client commitments, and matter strategy with the authorized firm owner.` },
  ],
  sources: b.sourceUrls?.map((url, i) => ({name: `Route source ${i + 1}`, url})) ?? researchSources,
});

const makeAugust14Research = (slug: string, title: string, excerpt: string, cluster: string, headlineStat: string, focus: string, question: string, finding: string, operational: string, limitation: string, relatedSlugs: readonly string[], published: string, sourceDate: string): ResearchPost => ({
  slug, title, excerpt, published, sourceDate, cluster, headlineStat, relatedSlugs, thumbnail: '/research-thumbnails/research-default.svg',
  sections: [
    { heading: 'Methodology', body: `This research asks ${question}. It compares the ABA guidance on protected client information, NIST Cybersecurity Framework 2.0, NIST SP 800-207 on zero trust, FTC safeguards guidance, HHS security guidance, ICO design and data-sharing guidance, SRA confidentiality standards, Law Society outsourcing guidance, CISA cloud guidance, OWASP logging guidance, and NIST incident-response guidance. These authorities serve different jurisdictions and purposes. They are used here as a comparative evidence set, not as a single law that governs every firm. The unit of analysis is a defined support handoff: a firm-approved instruction enters, a support worker performs a limited administrative action, and an authorized owner reviews the result. The study separates a factual check from a legal conclusion, a control from proof that the control worked, and a local operating choice from a universal requirement. It also treats date, source, actor, system, and reviewer as separate evidence fields. That separation matters because a neat record can still be based on a stale instruction or an unauthorized assumption.` },
    { heading: 'Research question', body: `${question} The practical test is whether a firm can explain the permitted purpose, the information needed, the systems touched, the action allowed, the event that stops the work, and the owner who decides what follows. ${finding} A support role should be able to show what it received, what it compared, what it entered or organized, and what it left unresolved. A reviewer should not have to infer whether an item was missing, rejected, superseded, or simply not examined. The evidence set should be small enough to protect confidentiality and complete enough to reconstruct the handoff. Where the sources do not answer a firm-specific question, the record should say that the firm made a local choice. That is more accurate than presenting a workflow preference as if it were a professional rule.` },
    { heading: 'Findings', body: `The source comparison produces four findings about ${focus}. First, purpose limits are operational controls, not just policy language. A worker who receives only the records and fields needed for the assigned task has fewer opportunities to misfile, disclose, or misread unrelated material. Second, provenance usually matters more than a completion tick. A reviewer needs the source identity, version or received date, and the exact field or record used. Third, uncertainty is a meaningful state. A conflicting identifier, unexpected recipient, ambiguous instruction, stale date, or request for advice should move the item to a visible exception state. Fourth, supervision must be attached to the work, not assumed from a vendor relationship or job title. ${finding} Taken together, these findings support an administrative boundary that is narrow, attributable, and easy to pause. They do not support a claim that any offshore arrangement is automatically compliant or safe.` },
    { heading: 'Evidence design', body: `A reviewable record for ${focus} has several layers. It begins with the matter or work-item identifier and the approved purpose, while excluding unrelated personal information. It then names the instruction, source location, source date, and version used. The action field describes what the worker did in neutral terms, including whether the original was left unchanged. An exception field records missing facts, conflicts, uncertainty, and the time the work stopped or was routed. A disposition field identifies the authorized reviewer, the decision supplied, and any new version created afterward. Finally, an access or event record should make the actor and time attributable without creating an uncontrolled duplicate of the client file. These layers answer different questions. What was requested? What source was available? What happened? What remains unknown? Who accepted or corrected the result? The evidence should be proportionate. More fields do not automatically make a record better if they collect information that the support role does not need.` },
    { heading: 'Topic-specific interpretation', body: `For ${focus}, the evidence supports a role boundary with named inputs, named systems, approved examples, and an explicit stop condition. ${operational} The worker may prepare, organize, compare against supplied criteria, or record approved facts. The worker should not decide privilege, legal sufficiency, strategy, materiality, eligibility, liability, or what advice a client should receive. A firm-side owner should choose an early review cohort with a defined denominator and period, such as the first 20 work items, a two-week queue, or a fixed sample from each matter type. That sample is a way to learn about the local process, not a universal performance claim. Review notes should classify observations by type, such as wrong source, incomplete field, stale instruction, unauthorized change, or unresolved judgment. A classification helps the firm improve the scope and the review gate without blaming a worker for a decision that the role was never allowed to make.` },
    { heading: 'Limits of the evidence', body: `${limitation} The authorities also do not establish that a particular firm has met its professional, contractual, privacy, or security obligations. A citation to NIST, an ethics opinion, or a regulator page shows the source of a principle. It does not prove that a permission set, contract, transfer, or review sample satisfies every applicable rule. Nor does a completed record prove that the underlying source was accurate. The comparison cannot resolve jurisdiction-specific questions about privilege, client consent, regulated information, cross-border transfer, or notification. It also cannot show whether a worker will perform consistently without a local observation period. A cautious conclusion therefore depends on scope, source currency, supervision, access administration, and the firm’s own review. If any of those conditions changes, the firm should reconsider the boundary rather than treating the previous approval as permanent.` },
    { heading: 'Practical test', body: `A firm can test ${focus} with a small, representative cohort. Define the task, the allowed information, the approved criteria, the reviewer, and the stop rules before the cohort begins. Give the worker the same source types and instructions used in ordinary work, but remove information that is not needed. The reviewer should compare the source, recorded action, exception state, and handoff against the written scope. Count defect categories instead of collapsing everything into one success rate. A useful log can distinguish wrong source, wrong matter, missing field, stale instruction, unauthorized change, missed escalation, and reviewer correction. Record the denominator, matter type, and period so later samples remain comparable. If recurring ambiguity appears, revise the task definition or add a review gate before expanding access. If an isolated factual error appears, correct the record and preserve the correction history. This test creates local evidence without pretending that one cohort proves a universal result.` },
    { heading: 'Operational consequences', body: `The research changes how a firm should describe ${focus}. The role brief should name the work as preparation or administration when that is what the worker is authorized to do. It should list the source types, fields, systems, reviewer, response window, and examples of work that must stop. The access request should follow the task definition rather than precede it. The queue should make exceptions visible instead of rewarding silent completion. The manager’s review should inspect both completed items and the reasons for pauses. When a client instruction, matter type, jurisdiction, or system changes, the firm should treat that change as a new control question. It may require a new permission review, a different sample, or a revised escalation path. The operational aim is not to make the support role responsible for every risk. It is to make responsibility legible so that the worker can complete permitted work and the authorized owner can make decisions with the relevant source in view.` },
    { heading: 'Bounded conclusion', body: `The evidence supports a bounded conclusion: ${focus} can be prepared for supervised administrative support when the purpose, access scope, source provenance, stop rules, and owner review are explicit. This conclusion is narrower than saying that the work can simply be outsourced. It says that a defined slice can be performed in a way that leaves legal judgment with the firm and gives the reviewer enough evidence to accept, correct, or escalate the handoff. The strongest measure is reconstructability for a specified matter, period, source set, and actor. For LegalServicesOffshore.com readers, that means evaluating a proposed support lane by its approved task boundary and review evidence rather than by a label such as assistant, coordinator, or researcher. Start with a small cohort, document exceptions, and expand only when the firm can explain both successful work and unresolved questions. The sources support that discipline; they do not replace the firm’s own legal and professional analysis.` },
    { heading: 'Review questions', body: `Before assigning ${focus}, a firm should answer these questions in its own control record. Which fields may the worker read, enter, or change? Which source controls when two records conflict? What exact event pauses the item? Who owns the review, and within what period? Which accounts, devices, and channels are permitted? How is a correction distinguished from a new version? What evidence is retained, for what purpose, and who may access it? How are client instructions and contractual restrictions reflected? What happens when the worker is asked for advice, a promise, or a judgment? What sample will be reviewed before the scope expands? These questions turn broad guidance into a local decision record. They also make it possible to compare an offshore support arrangement with an internal process without publishing unsupported claims about speed, savings, or outcomes.` },
    { heading: 'FAQs', body: `Does this report give legal advice? No. It compares authoritative guidance and describes a bounded administrative design. Can the support worker resolve an ambiguous legal issue? No. The worker should preserve the facts and route the issue to the designated owner. Is a completion mark enough? No. The source, action, exception, and review state should remain visible. Should every firm use these exact fields? No. The fields should reflect the matter, jurisdiction, client instruction, and system. Does offshore location remove firm responsibility? No. The firm remains responsible for its own professional, contractual, privacy, and security decisions.` },
  ],
  sources: researchSources,
});

