const august18ExplicitPosts: readonly ResearchPost[] = [
  { slug:'legal-support-email-triage-boundary-study', title:'Legal support email triage: research on routing without legal judgment', excerpt:'A source-backed study of how supervised legal support can sort inbox material while preserving uncertainty, confidentiality, and attorney ownership.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Scope Benchmarks', headlineStat:'Evidence distinguishes mechanical routing from legal prioritization.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-intake-support-control-benchmark','legal-client-follow-up-queue-controls'], sections:[
    {heading:'Research question and method',body:'This study asks when a legal support worker can triage an inbox without deciding which message deserves legal attention. I compared professional-responsibility guidance on protected communications with NIST risk-management and zero-trust guidance and OWASP guidance on attributable event records. The unit of analysis is one received message and the route applied to it, not the quality of the eventual legal response. I treated a requirement as a fact only when the source stated a security, confidentiality, or accountability principle. Recommendations about labels, queues, and review ownership are analysis. The comparison covers a supervised support role handling firm-approved criteria, individual accounts, and a named reviewer. It does not assume that a keyword, sender address, or subject line proves urgency, privilege, client authority, or a deadline. That narrow scope matters because email triage looks clerical while the hidden decision may affect legal rights or a client promise.'},
    {heading:'Evidence analysis',body:'The sources converge on provenance, minimum necessary access, and escalation when context is incomplete. Applied to legal support, a defensible route record identifies the mailbox or system, sender, recipients, received time, subject, attachment names, matter identifier supplied by the firm, and the exact routing rule used. A rule such as “messages from the court-notice mailbox enter the litigation review queue” is mechanical. A label such as “urgent because this may affect a filing” is an interpretation and belongs to the authorized owner. The same distinction applies to duplicate handling. A worker may flag two identical message identifiers, preserve both originals, and ask whether one is a duplicate; deletion or retention is a separate instruction. A message with an unexpected recipient or mismatched matter should remain linked to its source. The evidence therefore supports a queue state such as “missing matter identifier,” not a confident conclusion about where the message belongs.'},
    {heading:'Operating implications',body:'For a Philippines-based legal support arrangement, the safest design is a small set of firm-authored route rules with examples and explicit stop conditions. The worker can record receipt, apply a supplied category, attach a source link, and route uncertainty to a manager or attorney. Access should exclude unrelated mailboxes and use named accounts so the route is attributable. Early review should sample different message types rather than only easy messages: forwarded threads, attachments with conflicting names, client requests for advice, notices from unfamiliar domains, and messages containing several matters. Reviewers should classify corrections as wrong rule, missing source, wrong matter, unauthorized assumption, or failure to escalate. That classification tests the boundary itself. It does not create a success rate or establish legal compliance. A practical output is a preserved message plus a neutral queue record and owner, while substantive prioritization, privilege, response wording, and client communication remain outside support scope.'},
    {heading:'Limitations and conclusion',body:'This evidence cannot establish a universal triage taxonomy. Mail systems differ, jurisdictional duties differ, and a firm’s engagement letters or client instructions may impose stricter controls. Security guidance does not decide whether a communication is privileged, responsive, or legally urgent. A complete-looking route log also cannot prove that an email was understood or that an unseen message did not exist. The research supports supervised email triage only when the firm supplies narrow criteria, limits access, preserves the original, records the triggering facts, and makes uncertainty visible. The conclusion is not that support staff can prioritize legal work. It is that they can prepare a reviewable routing record when the route is mechanical and the decision gate is explicit. Any request for advice, legal significance, deadline judgment, or client-facing commitment should stop the queue and move to the named firm owner.'}
    , {heading:'Methodology',body:'The email study uses a deliberately small unit: one message, its supplied identifiers, the routing criterion, and the resulting queue state. I compared confidentiality and supervision principles in ABA Formal Opinion 477R with NIST CSWP 29 and OWASP logging guidance, then tested the principles against forwarded threads, mixed matters, attachments, and sender ambiguity. The sources establish control principles; the queue examples are my operational analysis. No performance rate or legal-priority claim is inferred.'}
    , {heading:'Limitations',body:'Mailbox rules vary by firm, practice, client agreement, retention setting, and jurisdiction. A sender, timestamp, or keyword can be wrong or incomplete, and a log can show an event without explaining intent. This research cannot decide privilege, urgency, deadline effect, authorization, or response wording. It also does not establish that a particular offshore arrangement satisfies a firm obligation.'}
    , {heading:'Evidence-led conclusion',body:'The evidence supports email triage only when routing is mechanical, provenance is retained, uncertainty is visible, and an authorized reviewer owns prioritization. The defensible output is a preserved message, the rule applied, and a named escalation—not an answer disguised as a label. For legal-support operations, that boundary is the useful finding: sorting can improve reviewability while legal judgment remains with the firm.'}
    , {heading:'Decision test',body:'A firm-side reviewer can test this boundary with a short, mixed sample: a routine filing receipt, a forwarded client thread, an attachment whose matter name conflicts with the subject, an unfamiliar sender, and a request that asks what the client should do. The expected support output is different for each item, but none requires a legal answer from the triage worker. The record should show the input, rule, queue, exception, and next owner. If the worker cannot explain the route without relying on intuition, the rule is not sufficiently bounded for delegation.'}
  ], sources:researchSources },
  { slug:'law-firm-document-metadata-quality-research', title:'Law-firm document metadata quality: research on reliable support records', excerpt:'An evidence-led examination of metadata capture, source provenance, and reviewer control in offshore legal document support.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Workflow Design', headlineStat:'Metadata quality is a provenance problem before it is a formatting problem.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['law-firm-document-intake-indexing','legal-document-version-control'], sections:[
    {heading:'Question and evidence scope',body:'The question is which document metadata can be captured by legal support without turning a descriptive record into a legal conclusion. I reviewed ABA confidentiality guidance, NIST governance and access principles, ICO data-protection-by-design material, and OWASP logging guidance. The evidence scope is administrative handling of documents already supplied by a firm: identifying a file, recording its source, associating it with a matter under an approved rule, and sending exceptions for review. The study does not assess the truth of a document’s contents, its discoverability, privilege, authenticity, or admissibility. Those distinctions are essential. “Received from the client mailbox at a stated time” is an observation if the source record supports it. “Authoritative final agreement” is a substantive conclusion unless an authorized owner has designated it. I therefore separate source facts from proposed controls and treat every missing field as an uncertainty rather than an invitation to guess.'},
    {heading:'What the sources imply',body:'Across the sources, reliable records share four features: a defined purpose, limited access, attributable changes, and enough context for later review. A metadata entry should connect the original filename, source location, received timestamp, matter label supplied by the firm, file type, apparent version, and person or system that recorded the entry. If a file has no author, that absence is data; it should not be filled with the name of the person who uploaded it. If two copies have the same name but different hashes or timestamps, the worker can preserve the distinction and flag it. A formatting change may be visible without proving that the underlying words changed. These details make a document register useful for an attorney reviewing a packet, but they do not authorize a support worker to decide which version controls, whether a document is responsive, or whether metadata should be stripped before production.'},
    {heading:'Distinctive operating test',body:'A useful test begins with a defined cohort such as one matter folder or one intake batch and measures record completeness by field, not by a single score. The worker records the supplied source, creates a stable internal identifier, and notes whether the item is an original, working copy, attachment, or unknown. A reviewer then compares the entry with the source and examines edge cases: scanned pages with no embedded metadata, files renamed by a client, duplicate attachments, files moved between systems, and documents whose date is visible only inside the image. Corrections should preserve the earlier value and explain why it changed. The review should also verify that the register did not collect unnecessary personal information. For offshore legal support, the role boundary is clear: organize observable attributes and preserve evidence; do not infer authorship, legal effect, completeness of production, or authenticity. The result is a repairable record rather than a false certificate.'},
    {heading:'Limitations and conclusion',body:'Metadata is dependent on system clocks, export behavior, naming conventions, and the quality of the original source. A register can be internally consistent while the source is wrong or incomplete. The cited guidance describes security and accountability principles, not a jurisdiction-neutral litigation metadata protocol. The study therefore cannot promise that a particular field set satisfies a court, client, or regulator. It does support a narrower conclusion: document support is safer when every important attribute has a source, every change is attributable, and unresolved identity or version questions are escalated. The firm should decide retention, privilege, responsiveness, and production rules. The support worker may prepare the register and identify conflicts under those rules, but must not resolve conflicts by selecting the most recent-looking file. Quality comes from visible provenance and review ownership, not from a polished spreadsheet or a complete-looking filename.'}
    , {heading:'Methodology',body:'This metadata study treats a document record as a bundle of fields rather than a filename. I compared ABA Formal Opinion 477R, NIST CSWP 29, and OWASP logging guidance, and examined version, author, matter identifier, received date, source location, and change history as separate observations. The sources provide security and accountability principles; the proposed field tests are analysis. The study does not measure a vendor, worker, or firm-wide error rate.'}
    , {heading:'Limitations',body:'Metadata can be copied incorrectly, inherited from a template, stripped by conversion, or rendered differently across systems. A complete field set cannot prove that a document is authentic, privileged, final, or legally relevant. The cited sources do not define every firm’s naming convention or retention duty, and this study cannot certify a repository or a chain of custody.'}
    , {heading:'Evidence-led conclusion',body:'Metadata quality should be judged by whether a reviewer can reconstruct origin, version, movement, and ownership, not by visual neatness alone. Offshore support may compare supplied fields, preserve originals, and flag contradictions; it should not silently normalize a disputed author, date, or matter identity. Provenance-first cleanup is therefore supportable, while authenticity and legal significance remain owner decisions.'}
    , {heading:'Decision test',body:'The practical test is a deliberately messy document set: a scanned pleading with an unreliable created date, a converted file with a changed author field, two versions with similar names, and a document moved between approved folders. Support records what each system shows, keeps the original identifiers, and marks the mismatch. The reviewer then decides which fields are authoritative and whether any correction is permitted. A quality measure should count visible discrepancies and preserved provenance, not reward a worker for making every record look uniform.'}
  ], sources:researchSources },
  { slug:'legal-support-client-portal-permission-review', title:'Legal support client-portal permissions: research on bounded access', excerpt:'A study of how legal support can inspect and document portal permissions while keeping access and client-facing decisions with the firm.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Hiring Controls', headlineStat:'Permission review should test granted capability, not assume intended use.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-support-offshore-portal-upload-checklist','law-firm-client-portal-support-workflow'], sections:[
    {heading:'Research question and method',body:'This research asks what a legal support worker can verify about a client portal without becoming the person who decides access, disclosure, or the meaning of a client message. The source review covers NIST zero-trust architecture, NIST Cybersecurity Framework, CISA cloud guidance, ABA protected-communication guidance, and ICO data-sharing principles. I compare their treatment of identity, least privilege, review, logging, and purposeful sharing with common portal tasks. The evidence supports controls; it does not establish that a portal configuration complies with every client agreement or professional rule. I define “permission review” narrowly as recording the account, role, visible matter scope, granted action, review date, and observed discrepancy. I do not treat a successful login as proof that access is appropriate, nor an inability to open a file as proof that the user has no access elsewhere.'},
    {heading:'Findings from access evidence',body:'A portal permission record is strongest when it separates entitlement from activity. A user may be able to view, upload, download, comment, invite, or administer without having performed each action. The reviewer therefore needs the role assigned, the matter or workspace boundary, the date checked, and the system evidence used. Support can compare those observations with a firm-approved access matrix and flag excess capability, missing access, shared credentials, dormant accounts, or a matter that appears in the wrong workspace. Support should not decide that an account is safe to retain or remove unless the firm has delegated that narrow action. A portal message also requires separation between receipt and response. Recording sender, timestamp, attachments, and routing owner is administrative; interpreting a request or promising an outcome is not. Permission evidence is valuable precisely because it makes the next decision visible rather than silently correcting the configuration.'},
    {heading:'A bounded review design',body:'The practical test is a two-person review of a defined sample: account records are compared with the approved role and the matter list, then each discrepancy is preserved with a screenshot or export reference allowed by the firm’s retention rules. The support role can check whether the account is individual, whether multifactor status is recorded where the system exposes it, whether access is broader than the assigned work, and whether a former worker remains listed. The firm owner decides removal, client notice, investigation, and any exception. A repair log should state what was observed, what source was consulted, what action was taken under instruction, and what remains unknown. This is especially important for offshore support because geography does not answer the access question. The firm must define permitted systems, data classes, hours, escalation timing, and whether the role may upload or only prepare files. A narrow account with reviewable evidence is more defensible than broad access justified by convenience.'},
    {heading:'Limitations and conclusion',body:'Portal interfaces change, exports may omit inherited permissions, and the same user may have access through connected tools. The cited standards describe principles rather than a complete portal audit procedure. A permission snapshot cannot prove that a file was not viewed, copied, or shared through another channel, and it cannot determine whether a client consented to cross-border support. The research supports a factual review lane: identify the account and granted capability, compare it with a firm-owned matrix, preserve the evidence, and escalate discrepancies. It does not support autonomous access decisions or client-facing explanations. The conclusion is that legal support can improve portal governance when the role is given the least capability necessary, uses individual credentials, records checks and exceptions, and leaves approval, removal, disclosure, and substantive communication with the authorized firm owner.'}
    , {heading:'Methodology',body:'The permission study compares least-privilege and accountability principles from NIST CSWP 29 and OWASP logging guidance with ABA Formal Opinion 477R’s confidentiality and supervision concerns. Its unit is a permission grant: named user, resource, level, purpose, approver, time, and removal state. I then apply that model to portal invitations, shared links, external recipients, and inherited access. These are control analyses, not a test of any portal product.'}
    , {heading:'Limitations',body:'A portal record may not reveal an account’s real identity, a client’s consent, a hidden inherited permission, or the legal effect of disclosure. Interfaces and role names differ, and access may change between review and action. The sources cannot decide who is entitled to a file or whether a particular transfer is permitted. Those questions require the firm’s current instructions and authorized judgment.'}
    , {heading:'Evidence-led conclusion',body:'Permission review is a useful administrative lane when it records capability rather than assuming entitlement. Support can compare a supplied request with a named permission, preserve approval evidence, and flag unusual recipients or levels. It must stop at identity, consent, scope, or disclosure uncertainty. The result should be an auditable access question for the firm, not a support-created authorization.'}
    , {heading:'Decision test',body:'A useful review sample includes a named internal user, a departing user whose access should be removed, an external guest, a shared link, and an account that appears to inherit a higher permission than requested. For each, the support record states the observed capability, request, approving owner, and unresolved identity or scope issue. It does not infer that the person is entitled to the matter. The reviewer can then distinguish a stale permission, a missing approval, a portal configuration question, and a substantive access decision.'}
  ], sources:researchSources },
  { slug:'legal-intake-duplicate-party-review', title:'Duplicate-party review in legal intake: research on identity uncertainty', excerpt:'A source-backed analysis of how support can flag possible duplicate parties without merging identities or making an intake decision.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Scope Benchmarks', headlineStat:'Name similarity is a signal for review, not proof of identity.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['law-firm-intake-source-verification','legal-intake-support-control-benchmark'], sections:[
    {heading:'Question and method',body:'This study asks whether legal intake support can identify possible duplicate party records without deciding that two people or entities are the same. I compared confidentiality and minimum-necessary handling principles from ABA and ICO guidance with NIST identity and access controls and data-quality ideas in public records practice. The unit is a pair of intake records and the evidence that makes them appear similar. I distinguish observable matches—spelling, supplied email, phone, address, organization number, or matter reference—from the conclusion that the records represent one legal party. That conclusion may affect conflicts, notices, or representation and therefore needs the firm’s process. The review is about queue preparation, not conflict checking, eligibility, identity verification, or advice. A support worker may preserve differences and ask a precise question; the worker should not collapse ambiguity because a form requires one clean name.'},
    {heading:'Evidence and risk',body:'Duplicate review is often treated as a search problem, but the source evidence suggests it is an uncertainty-management problem. A name match can be coincidental, transliterated, abbreviated, or shared by relatives. An address can identify a household or registered office rather than one individual. An email can be a role account. A support record should show which fields matched, which did not, where each value came from, and when it was captured. It should preserve the submitted spelling instead of normalizing away the difference. If a corporate party has a similar name, the registration number or supplied organizational record may be more useful than punctuation. None of these signals proves ownership or authority. The safe output is “possible duplicate—review required,” linked to both source records, with the reason for the flag. A clean merge hides the very uncertainty the attorney or intake manager needs to see.'},
    {heading:'Decision boundary in practice',body:'A firm can test the lane using historic intake examples that have been minimized and approved for training. The support worker applies a written matching rule, records the matched fields, and stops when the rule finds an ambiguous case. A reviewer checks whether the flag is understandable without reopening the entire intake. Categories should include exact supplied identifier, similar name only, shared contact, conflicting identifier, and insufficient information. The worker may request a missing field using firm-approved wording, but may not tell a prospective client that a matter is accepted, rejected, conflicted, or safe to proceed. Access should be limited to the intake workspace and the records needed for comparison. Where the firm instructs a merge, the action should retain the prior values and approval trail. The result is an evidence packet for a human decision, not an automated identity conclusion.'},
    {heading:'Limitations and conclusion',body:'The sources do not provide a universal identity threshold, and legal consequences of a mistaken merge vary by practice and jurisdiction. Structured identifiers may be absent or inaccurate; names and addresses can change; and duplicate detection cannot reveal a record that was never entered. A flagged pair therefore does not establish a conflict, while an unflagged pair does not prove uniqueness. The evidence supports a narrow intake support role that preserves submitted values, explains similarity, protects access, and escalates uncertainty. It does not support autonomous merging, conflict clearance, or a representation decision. The conclusion is simple: legal intake benefits when duplicate review produces transparent questions instead of confident guesses. Firm owners should define the fields, review authority, client wording, retention rule, and stop conditions before assigning the task to offshore support.'}
    , {heading:'Methodology',body:'The duplicate-party study separates similarity from identity. I compared ABA confidentiality and supervision guidance with NIST CSWP 29 and OWASP logging principles, then examined name, address, organization, matter, and source-document fields as independent signals. The unit is a candidate pair and the evidence that produced the flag. Similarity thresholds and examples are analytical tests, not proof that two records describe the same person or entity.'}
    , {heading:'Limitations',body:'Names change, transliteration creates variants, households share addresses, and corporate entities can have related names. Missing identifiers produce both false positives and false negatives. A database match cannot establish legal identity, conflict status, party capacity, consent, or authorization to merge. The sources support traceability and confidentiality but provide no universal threshold for duplicate resolution.'}
    , {heading:'Evidence-led conclusion',body:'A legal intake support role can surface a possible duplicate if it preserves both records, identifies the matching fields, and routes the pair without merging or suppressing either entry. The evidence-led decision is not “same party”; it is “these records warrant owner review for this stated reason.” That modest output protects the intake record and keeps identity and conflict judgments with the firm.'}
    , {heading:'Decision test',body:'A representative intake sample should include two people with the same surname, one person whose name is transliterated differently, two matters for the same organization, and a genuinely repeated submission. Support lists the exact fields that triggered each flag and keeps the records separate. The owner decides whether the candidate concerns identity, a conflict check, a repeat inquiry, or no issue at all. That sequence matters: the more consequential the possible match, the less appropriate it is to collapse uncertainty into a database merge.'}
  ], sources:researchSources },
  { slug:'legal-support-deadline-source-reconciliation', title:'Legal support deadline source reconciliation: research on conflicting dates', excerpt:'An evidence-led study of reconciling dates from matter systems and documents without declaring a legal deadline.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Scope Benchmarks', headlineStat:'A date comparison can expose conflict; it cannot resolve legal effect.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-deadline-escalation-matrix','law-firm-offshore-support-deadline-source-check'], sections:[
    {heading:'Research question and scope',body:'The question is how legal support can compare deadline-related dates from approved sources while avoiding a legal conclusion about which date controls. I reviewed professional confidentiality guidance, NIST accountability and incident principles, and public court and information-governance materials as examples of source dependence. The method treats each date as a sourced observation with a label: document date, received date, entered date, instruction date, or system-derived date. It does not treat a calendar field as a ruling. The study covers preparation of a reconciliation record for an attorney or matter owner. It excludes calculating a filing deadline, interpreting service, applying a jurisdictional rule, deciding an extension, or telling a client what will happen. That boundary is necessary because two apparently precise dates can arise from different events and only a qualified owner can decide which legal rule applies.'},
    {heading:'Analysis of date evidence',body:'A useful reconciliation record keeps competing dates side by side. For each value, support should record the source title or system, visible time zone if supplied, the person or system that entered it, retrieval time, and the exact surrounding instruction. “Received by the firm on Tuesday” is not necessarily “served on Tuesday.” “Due date in the task system” is not necessarily “court deadline.” If a PDF shows one date and an email references another, the worker should preserve both and describe the relationship without choosing. A calendar alert can be created only under an approved instruction, and any uncertainty should be conspicuous rather than buried in a note. NIST-style event attribution helps reconstruct what was seen and changed, while confidentiality principles limit unnecessary copying. The evidence supports a red flag such as “conflicting date sources,” not a replacement date or urgency judgment.'},
    {heading:'Reconciliation test and role boundary',body:'The firm can test this work with a sample of matters containing different source types: court notices, client emails, internal instructions, portal receipts, and calendar entries. Support extracts only the fields authorized by the firm, links each value to its source, and identifies missing time zones or unexplained transformations. The reviewer then decides whether the issue is a data-entry correction, a question for counsel, or a time-sensitive escalation. Support may send a firm-approved internal alert that a conflict exists, but should not write “deadline is tomorrow” unless the authorized owner supplied that statement. A good record preserves the prior value, the new instruction, the person approving it, and the time of change. The firm should define who can update a calendar and who must be called immediately. The task is valuable because it makes uncertainty visible early; it is unsafe when the reconciliation sheet is mistaken for legal calculation.'},
    {heading:'Limitations and conclusion',body:'Date evidence is vulnerable to clock settings, missing time zones, late entry, amended orders, and incomplete matter histories. The cited sources do not prescribe a deadline computation for every court or engagement. A reconciled list cannot prove service, tolling, validity of an extension, or the legal effect of a document. It also cannot eliminate the need to verify the source. The research supports offshore legal support in comparing and preserving date evidence under firm-authored criteria. It does not support selecting the controlling date, calculating legal time, or making a client promise. The conclusion is that a source-linked conflict record is the right deliverable: each date remains visible, the difference is stated neutrally, and the named attorney or matter owner decides the next action. Any system that hides alternative dates to look orderly increases rather than reduces risk.'}
    , {heading:'Methodology',body:'The deadline study treats each date as an observation with a source, date type, time zone, received time, and owner. I compared ABA confidentiality and supervision guidance, NIST CSWP 29, and OWASP logging principles, then analyzed conflicts between a pleading, a docket entry, a calendar, and a task note. The sources support attributable comparison; they do not supply a rule for deciding which date controls a matter.'}
    , {heading:'Limitations',body:'Deadlines depend on jurisdiction, procedural posture, service facts, holidays, extensions, local rules, and the exact document. Systems can use different time zones or stale data. A date comparison cannot establish legal effect, tolling, waiver, or client notice. This research therefore cannot replace counsel’s calculation, confirmation, or escalation instruction.'}
    , {heading:'Evidence-led conclusion',body:'Source reconciliation is valuable when it makes disagreement impossible to miss. Support can preserve competing dates, identify their sources, show the comparison time, and route the conflict to the named owner. It should never choose the operative deadline because one field looks newer. The evidence supports a visible unresolved state, which is safer and more useful than a confident but unsupported calendar value.'}
    , {heading:'Decision test',body:'The decision test should compare a docket entry, a served document, a firm calendar, and an instruction that changes after receipt. Support records each date and its source rather than ranking them. It identifies missing service detail, inconsistent time zone, or an unexplained extension as separate exceptions. The authorized reviewer can then confirm the operative calculation or request more facts. A report that says “deadline conflict—owner review required” is a complete administrative result even when the legal answer is not yet known.'}
  ], sources:researchSources },
  { slug:'legal-support-redaction-candidate-evidence', title:'Redaction candidates in legal support: preserving attorney review', excerpt:'A study of mechanically identified redaction candidates, source preservation, and the boundary between preparation and legal judgment.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Hiring Controls', headlineStat:'Candidate preparation is not a privilege, responsiveness, or production decision.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-document-redaction-review-boundary','legal-privilege-review-administration'], sections:[
    {heading:'Question and methodology',body:'This research asks which parts of redaction preparation can be assigned to legal support without deciding what must be withheld. I compared ABA confidentiality guidance, NIST access and logging principles, OWASP event-record guidance, and public professional material concerning supervised legal work. The unit of analysis is a document location identified under a firm-approved mechanical criterion, such as a supplied pattern for an account number. The evidence does not establish that the candidate is privileged, responsive, confidential, or legally protected. I separate the observable match from the reason for redaction and the final release decision. The study assumes the original document is preserved, the support worker has limited access, and an authorized reviewer owns the criteria. It therefore evaluates a preparation lane, not a promise that pattern matching can replace legal review.'},
    {heading:'Evidence analysis',body:'A candidate record should identify the source file, page or field location, criterion used, visible text category without copying more sensitive material than necessary, and reviewer state. The original must remain unchanged. If the pattern creates a false positive—an account number in a public footer, a date that resembles an identifier, or a name that matches a supplied list—the example should remain visible for the reviewer. A candidate list should distinguish “mechanical match,” “reviewed,” “approved,” and “rejected,” because these states have different meanings. Confidentiality guidance supports limiting the workspace and recipients; logging guidance supports attributable changes. Neither source authorizes support to expand a search rule when the document context looks important. The worker may say where a supplied pattern appears. The worker may not say why a passage is privileged, whether a production is complete, or whether a redaction prevents waiver.'},
    {heading:'A reviewable operating test',body:'A firm can evaluate the boundary on a minimized document set with known examples and deliberately difficult near-matches. Support records the input rule, source identity, location, and untouched original, then sends the candidates to counsel or the designated reviewer. Measurement should report categories—missed match, false positive, wrong page, source altered, missing provenance, or unresolved context—rather than a single accuracy claim. The reviewer decides whether the rule was appropriate and whether any new criterion may be used. If a production copy is created, the release path should record approval separately from preparation. An offshore support role may also check that page counts and candidate identifiers line up, but should not certify that every responsive item was found. The handoff should make it easy to compare the proposed change with the source and to reverse an unapproved change. This preserves both quality and authority.'},
    {heading:'Limitations and conclusion',body:'Redaction is contextual, jurisdiction-specific, and often tied to privilege, privacy, discovery, or client instructions. Mechanical rules miss meaning and can over-include ordinary text. Logs and source copies can show what was done, but cannot prove that the legal judgment was correct. The cited guidance is not a universal redaction protocol. The evidence nevertheless supports a narrow preparation role when the rule is explicit, access is limited, originals are preserved, all locations are attributable, and an authorized reviewer approves disposition. The conclusion is that “candidate” must remain a factual status. Turning it into “withheld” or “safe for production” silently transfers legal judgment to the wrong role. Support creates value by exposing likely locations and preserving an audit trail; counsel decides the basis, scope, exceptions, and release.'}
    , {heading:'Methodology',body:'The redaction study analyzes a candidate location, not a redaction decision. I compared ABA Formal Opinion 477R with NIST CSWP 29 and OWASP logging guidance, then considered mechanically detectable patterns, source preservation, access records, and reviewer disposition. The unit is a proposed location tied to an unchanged original. The sources support confidentiality, attributable action, and review; the candidate rules are operational analysis, not privilege or responsiveness standards.'}
    , {heading:'Limitations',body:'A keyword, field pattern, or document label cannot determine privilege, responsiveness, confidentiality, waiver, or production scope. OCR can miss text, tables, images, and handwriting; a redaction can also remove context needed by a reviewer. The cited sources do not decide the matter-specific legal basis for withholding content, and a clean output cannot prove a complete review.'}
    , {heading:'Evidence-led conclusion',body:'Candidate preparation is supportable only if the original remains available, each proposed location is attributable, and an authorized reviewer accepts or rejects it. Support can mark a mechanically identified location and preserve the reason for the flag. It cannot apply a legal category by intuition or certify a production set. The evidence-led boundary is preparation with provenance, followed by firm-owned legal review.'}
    , {heading:'Decision test',body:'A bounded sample should include a repeated name, a personal address, an attorney-client phrase supplied in a search term, a spreadsheet cell, an image, and an OCR failure. Support records the candidate location and preserves the untouched source. The reviewer decides whether the proposed action is relevant, privileged, responsive, or unnecessary. This sample tests the handoff rather than the worker’s legal judgment. It also reveals whether the system can display page, field, and version provenance when a reviewer needs to inspect the original.'}
  ], sources:researchSources },
  { slug:'law-firm-knowledge-base-source-expiry', title:'Legal knowledge-base source expiry: research on reviewable support content', excerpt:'An analysis of source ownership, review dates, and expiry states for internal legal-support guidance.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Workflow Design', headlineStat:'A trusted knowledge entry still needs a current source and accountable owner.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['offshore-legal-knowledge-base-maintenance','legal-research-authority-currency'], sections:[
    {heading:'Question and method',body:'This study asks how legal support can maintain a knowledge entry when the source may change, without allowing an internal note to become unapproved legal advice. I compared ICO accountability and data-protection-by-design guidance, NIST governance and access principles, ABA confidentiality guidance, and professional outsourcing material. The evidence scope is maintenance of source metadata: title, owner, version or retrieval date, review status, and link to the approved instruction. It does not decide whether the instruction remains legally correct. I distinguish the fact that a page was retrieved from the analysis that its content is suitable for a particular matter. The proposed role may identify missing ownership, broken links, stale review dates, or differences between an entry and its source. It may not silently rewrite meaning, extend an expiry date, or publish a generalized answer from a one-off attorney conversation.'},
    {heading:'Why expiry is substantive',body:'A knowledge entry has at least two lifetimes. The external source may change, and the firm’s approved procedure may change even when the source does not. A date-visible record lets a reviewer ask which version was used and who accepted it. A support worker can compare the title, version, retrieval date, and quoted field names against the stored source, but should not assume that unchanged wording means unchanged legal effect. Examples are especially risky: a sample intake instruction may depend on a jurisdiction, client, or matter type. The record should label scope, owner, review trigger, and prohibited inference. If the owner is unavailable or the source link fails, the appropriate state is “review required,” not “confirmed current.” Access controls also matter because internal guidance may contain confidential matter examples. Maintenance should remove unnecessary client facts and keep the instruction separate from the source evidence.'},
    {heading:'Operational experiment',body:'A firm can pilot an expiry queue with a defined set of support instructions. For each entry, support records source identity, last review, owner, scope, next review trigger, and observed discrepancy. It can classify findings as current evidence, broken source, missing owner, scope mismatch, stale date, or substantive question. A reviewer then determines whether to approve, revise, archive, or replace the entry. The worker may draft a neutral comparison, but approval belongs to the firm. The test should include a source that changed, an entry with a superseded form, a rule that applies only to one practice group, and an example containing unnecessary personal information. These cases reveal whether the knowledge system makes uncertainty visible. A date alone is not a control if no one owns the decision. The useful output is a queue with evidence and disposition, not a claim that every page is current.'},
    {heading:'Limitations and conclusion',body:'Review intervals depend on practice, jurisdiction, system, and client instruction. The sources do not establish which legal content is safe to retain or how frequently every entry should be checked. A source link may be available while the firm’s interpretation is obsolete, and a current rule may not apply to a particular matter. The research supports source-owned, access-limited, date-visible knowledge maintenance. It does not support support staff making legal policy or presenting an internal note as advice. The conclusion is that expiry is a useful uncertainty state: it prompts an accountable owner to review the source, scope, and instruction before the entry is reused. Continuity improves when stale content is visibly paused rather than silently treated as authority. For offshore support, this is a clear administrative contribution with a strict boundary around interpretation and approval.'}
    , {heading:'Methodology',body:'The source-expiry study compares ABA Formal Opinion 477R, NIST CSWP 29, and OWASP logging guidance through three objects: the external source, the firm’s approved instruction, and the knowledge entry that cites them. I examined changed links, superseded forms, missing owners, and entries whose scope differs from the current queue. The sources establish accountability and protection principles; the review interval and expiry states are analysis, not a universal schedule.'}
    , {heading:'Limitations',body:'A live link does not prove that its content remains correct for a matter, and a current external source may not reflect a firm’s engagement or local rule. Access logs can be incomplete, owners can change, and source dates may be unclear. This study cannot determine the legal currency of every entry or authorize support staff to update substantive policy.'}
    , {heading:'Evidence-led conclusion',body:'Expiry should be treated as an explicit uncertainty state, not a silent invitation to reuse. Support can record the source version, check date, changed scope, and owner requested for review, then pause the entry. The evidence supports a reviewable knowledge base for law-firm support; it does not support support-created legal policy. Reuse becomes defensible only after the responsible owner confirms scope and currency.'}
    , {heading:'Decision test',body:'A source-maintenance sample should contain a broken link, a source that changed after the entry was written, a current source with a narrower scope, an entry without an owner, and an approved firm instruction that supersedes an external page. Support records the difference and pauses reuse where the scope is unclear. The owner confirms whether to revise, archive, or retain the entry. This test measures whether stale authority becomes visible; it does not turn a support worker into the person who updates legal policy.'}
  ], sources:researchSources },
  { slug:'legal-support-matter-status-evidence', title:'Matter status reporting for legal support: evidence without outcome claims', excerpt:'Research on reporting observed case-management states while keeping predictions, legal assessments, and client communication with the firm.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Scope Benchmarks', headlineStat:'A status report is strongest when every material statement has a source.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-matter-status-reporting','law-firm-offshore-support-matter-status-source-board'], sections:[
    {heading:'Question and evidence scope',body:'The research question is what makes a legal matter status update useful without overstating what the record proves. I compared NIST and OWASP principles for attributable records with ABA confidentiality guidance, ICO accountability material, and professional outsourcing guidance. The unit is one status statement and the source record behind it. “Draft uploaded at 14:00” is an observable event if the system supports it. “Matter is on track” or “client is likely to win” is an interpretation and is outside a support role unless an authorized owner supplies the statement. The study covers administrative reporting from approved systems and excludes legal analysis, forecasting, strategy, and client advice. I treat missing data as a finding. A dashboard that fills every blank with a reassuring label is not more accurate; it is less honest about what the record cannot show.'},
    {heading:'Findings about status evidence',body:'A defensible status record separates completed action, pending action, missing input, exception, and owner decision. It names the source system, timestamp, last recorded action, assigned owner, and any instruction that limits interpretation. “Awaiting client” should link to the request or firm-approved note; it should not imply that the client received or understood it. “Review requested” should identify the reviewer and request time; it should not imply that review occurred. Support can reconcile a matter board with a document register and flag conflicts such as a draft marked complete, a deadline with no source, or a closed task with a later email. It may state that the records disagree. The matter owner decides whether the discrepancy reflects unrecorded work, a data-entry error, or a substantive issue. This preserves useful context without converting administrative state into an outcome claim.'},
    {heading:'A measured reporting design',body:'The firm can test reporting on a fixed weekly sample and compare each sentence with its source. Support prepares the report using a defined field list, retains links to the source, and labels the observation time. Reviewers classify corrections as stale source, wrong matter, unsupported interpretation, missing owner, or incomplete exception. These categories show where the system needs better fields or instructions. A support worker may enter an approved factual correction and preserve the prior value, but may not erase an uncomfortable status to make a dashboard appear complete. If a client-facing update is needed, the matter owner approves its wording. A Philippines-based support role can make the record timely and traceable while the firm retains responsibility for legal significance. The report’s purpose is to help a decision-maker see what is known, unknown, and waiting—not to promise a result.'},
    {heading:'Limitations and conclusion',body:'Status fields depend on data quality, user habits, integrations, and matter-specific definitions. A factual dashboard cannot reveal unrecorded work or prove legal sufficiency. The cited guidance supports accountability and confidentiality but does not define a universal matter-status vocabulary. The research therefore supports source-linked reporting with explicit unknowns and owner review. It does not support assigning risk, predicting outcomes, approving client communications, or presenting a stale record as current. The conclusion is that reporting creates value when it is modest about what the evidence shows: action, source, time, owner, exception, and next decision. If a statement cannot be tied to a source, it should be labeled as an owner analysis or removed from the support report. That discipline keeps administrative visibility from masquerading as legal judgment.'}
    , {heading:'Methodology',body:'The status study compares NIST and OWASP event-record principles with ABA confidentiality and supervision guidance and ICO accountability material. Its unit is one sentence in a report and the source event behind it. I tested action logs, document registers, task boards, and approved request notes for completed, pending, missing, and conflicting states. A source-backed observation is treated as fact; forecasts and explanations are explicitly analysis.'}
    , {heading:'Limitations',body:'Status systems omit unrecorded work and may lag behind email, court activity, or a client instruction. Field meanings differ across firms, and a timestamp cannot show quality or legal sufficiency. The sources do not create a universal vocabulary or authorize prediction of outcome. This study cannot validate a matter’s substantive position or approve client-facing language.'}
    , {heading:'Evidence-led conclusion',body:'A support status report earns trust by showing its source, time, owner, exception, and unknowns. It may reconcile records and state that they disagree, but should not convert “draft uploaded” into “matter on track.” The evidence supports bounded visibility for a law firm and offshore support partner; outcome, risk, strategy, and communication remain the responsible firm owner’s decisions.'}
    , {heading:'Decision test',body:'A status sample should include a completed upload, a task marked complete with no file, a client request awaiting a response, a board item that conflicts with a document register, and a matter whose owner changed. Support states the observable record and preserves the source for each exception. The owner decides whether work was actually completed, whether a client update is needed, and how the matter should be characterized. This keeps a status report useful without rewarding unsupported certainty.'}
  ], sources:researchSources },
  { slug:'legal-support-translation-source-preservation', title:'Legal translation handoffs: research on preserving meaning for review', excerpt:'An evidence-led examination of translated legal-support materials, source preservation, and reviewer control.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Hiring Controls', headlineStat:'Version provenance helps a reviewer inspect meaning; it cannot certify equivalence.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-support-offshore-translation-handoff','legal-document-version-control'], sections:[
    {heading:'Question and methodology',body:'This study asks what evidence should accompany a translated legal-support document before an authorized reviewer relies on it. I compared ABA confidentiality guidance, ICO data-sharing and design principles, NIST access controls, and professional outsourcing guidance. The unit is a source document, a working translation, and the handoff between them. The sources support protecting information, limiting access, preserving versions, and recording responsibility. They do not prove that a translation preserves legal meaning, satisfies a filing rule, or is fit for advice. I therefore distinguish page and field completeness from linguistic or legal quality. Support may coordinate a request, preserve the original, record language and version details, and identify an unresolved terminology question. It may not certify equivalence, select a consequential legal term by intuition, or delete the source after delivery. The methodology is a role-boundary analysis, not a translation accuracy benchmark.'},
    {heading:'Evidence analysis',body:'A reviewable package keeps the original, working version, target language, requested purpose, date, reviewer, and terminology instruction together. It records whether every page, attachment, table, and signature block is present and identifies text that was unreadable or omitted. An approved glossary can be applied as a supplied criterion, but a missing glossary term is a question, not permission to improvise. Version names should distinguish source, draft, reviewed output, and superseded copy. Access should be limited to the matter and the people authorized by the firm. A support worker can map paragraphs or fields and report that two versions differ; the reviewer decides whether the difference changes meaning. The distinction is important for offshore support because preparation can be useful without transferring professional responsibility. A clean English file is not automatically a faithful or legally equivalent document.'},
    {heading:'Handoff test and boundaries',body:'A firm can test the lane with representative documents containing tables, handwritten marks, defined terms, stamps, and ambiguous phrases. Support records the source and output identifiers, page counts, missing elements, terminology questions, and the person to review. The reviewer evaluates meaning and gives disposition. Defects should be categorized as missing source, omitted text, wrong version, glossary gap, formatting loss, or substantive question. A support worker may correct a transcription under an explicit instruction and retain the prior version, but should not resolve a disputed term silently. Client-facing delivery, certification, notarization, filing, and advice remain with the authorized owner. This design also limits unnecessary copies and makes it possible to retrace which version was used. The evidence supports coordination and preservation, not a claim that a language task is complete because a file was exported.'},
    {heading:'Limitations and conclusion',body:'Language, jurisdiction, document purpose, layout, and client instruction determine the appropriate level of review. The sources do not establish a universal translation threshold or identify a qualified reviewer for every matter. A source register cannot prove semantic equivalence, and page-count matching cannot reveal a mistranslated phrase. The research supports translation coordination when source and version provenance are visible, access is controlled, uncertainty is listed, and a qualified owner reviews meaning. It does not support legal interpretation or approval for filing. The conclusion is that preservation is the central control: keep both versions, show what was requested, identify what remains uncertain, and make the review decision explicit. Offshore support can make that handoff orderly and inspectable while the firm retains judgment over language, legal effect, and communication.'}
    , {heading:'Methodology',body:'The translation study uses the source document, working version, request purpose, and reviewer as its unit of analysis. I compared ABA Formal Opinion 477R, NIST CSWP 29, and OWASP logging principles with guidance on controlled information handling, then tested page order, attachments, tables, defined terms, stamps, and terminology questions. The sources support provenance and access control; they do not measure linguistic equivalence or certify a translation.'}
    , {heading:'Limitations',body:'A matching page count can hide an omitted phrase, mistranslated term, or changed legal effect. Language, jurisdiction, document purpose, glossary authority, and reviewer qualifications all matter. A source register cannot establish semantic accuracy, and the cited control guidance cannot decide whether a translated document is fit for filing, advice, or client delivery.'}
    , {heading:'Evidence-led conclusion',body:'Preserving source and working versions is the defensible contribution of legal translation support. A worker can record completeness observations, retain terminology questions, and route the package to an authorized reviewer. The worker should not improvise a consequential term or certify equivalence. The evidence supports an inspectable handoff, while linguistic meaning and legal effect remain with the firm.'}
    , {heading:'Decision test',body:'A handoff sample should include a source with a table, one with a seal or signature, one with a defined term absent from the supplied glossary, one with an unreadable scan, and one with a late replacement page. Support records page and attachment completeness, version identifiers, and terminology questions. The reviewer decides whether the working text is accurate and fit for its purpose. The test is successful when uncertainty is preserved and easy to inspect, not when the support record claims that the translation is certified.'}
  ], sources:researchSources },
  { slug:'legal-support-incident-timeline-reconstruction', title:'Reconstructing a legal-support incident timeline: what evidence can show', excerpt:'A study of factual event reconstruction after a suspected access or confidentiality concern, without assigning intent or legal significance.', published:'2026-08-18', sourceDate:'2026-08-18', cluster:'Workflow Design', headlineStat:'A timeline is evidence of recorded events, not a verdict about what happened.', thumbnail:'/research-thumbnails/research-default.svg', relatedSlugs:['legal-support-incident-evidence-readiness','remote-legal-support-incident-response'], sections:[
    {heading:'Research question and scope',body:'The question is which support records help reconstruct events after a suspected access or confidentiality incident. I reviewed NIST incident-handling and cybersecurity guidance, CISA cloud-security material, OWASP logging guidance, and ABA protected-communication guidance. The unit is an event record: account, action, resource, event time, record time, source system, and retrieval context. The sources support preservation, attribution, protected logs, and escalation. They do not allow a support worker to determine intent, breach status, notification duty, or culpability. The study evaluates a narrow evidence-collection lane under incident-owner instruction. It does not prescribe an investigation plan for every firm or jurisdiction. This distinction keeps the timeline factual. A gap in logs is a gap; it is not permission to infer that no access occurred or that a person caused the concern.'},
    {heading:'What makes a timeline reliable',body:'A useful timeline distinguishes when an event occurred from when it was recorded and identifies time zone or clock limitations. It preserves the account label as shown, the resource identifier, action type, event identifier, source system, and confidence or gap note. Related events should remain separate until the incident owner connects them. A download, permission change, and external message may be relevant, but their sequence alone does not prove a disclosure. Support can retrieve approved logs, record the query used, preserve the source location, and note unavailable systems or retention limits. It should not merge two similar usernames, redact inconvenient entries, or edit a timestamp to make the sequence clearer. Confidentiality principles also require collecting only what the investigation needs. A small, protected evidence set is safer than a broad uncontrolled copy of matter data.'},
    {heading:'Practical reconstruction test',body:'The firm can test the support lane with a controlled event set containing clock differences, failed logins, inherited permissions, duplicate events, and a missing record. Support prepares a chronological table while keeping original event identifiers and source references. The incident owner checks whether the table distinguishes observation from inference and whether every gap is visible. Findings can be categorized as unavailable log, ambiguous identity, clock variance, unauthorized alteration, unsupported connection, or confirmed source event. Support may preserve evidence and follow a hold instruction; it may not accuse an individual, decide that information was disclosed, contact a client, or delete records to tidy the table. The role can also document containment actions performed under direction. This design is valuable because it lets technical or legal owners reason from the same evidence without forcing a support worker to supply the legal conclusion.'},
    {heading:'Limitations and conclusion',body:'Logs can be incomplete, altered by system settings, unavailable across platforms, or generated after the fact. A timeline cannot establish intent, legal duty, or the full scope of information viewed. The cited guidance supports evidence integrity and escalation but does not answer jurisdiction-specific notification questions. The research supports a narrow reconstruction role with protected records, attributable queries, explicit gaps, and immediate escalation to the incident owner. It does not support investigation conclusions or client communication. The conclusion should remain proportional to the records: the timeline can state what a system recorded, when it was retrieved, and what cannot be known from that source. Keeping that boundary preserves the usefulness of offshore support while preventing an administrative chronology from being mistaken for a legal finding.'}
    , {heading:'Methodology',body:'The incident study uses an event record as its unit: account, resource, action, event time, record time, source system, and retrieval context. I compared NIST incident and cybersecurity guidance, CISA cloud-security material, OWASP logging guidance, and ABA confidentiality principles. I distinguished recorded facts from connections an investigator might later infer. The test cases include clock differences, failed logins, permission changes, duplicate events, and missing records.'}
    , {heading:'Limitations',body:'Logs can be incomplete, misconfigured, unavailable after retention periods, or generated in different time zones. Similar account names do not prove identity, and event sequence does not prove intent or disclosure. The sources do not answer notification, breach, culpability, or preservation questions for every jurisdiction. This research cannot replace the incident owner, counsel, or a formal investigation.'}
    , {heading:'Evidence-led conclusion',body:'A support role can help reconstruct a timeline when it preserves original event identifiers, records retrieval queries, marks gaps, and protects the evidence set. It should not accuse a person, declare a breach, contact a client, or tidy away inconvenient records. The evidence-led conclusion is deliberately narrow: a timeline can show what a system recorded and what it cannot show, leaving legal significance to the authorized owner.'}
    , {heading:'Decision test',body:'A controlled reconstruction sample should include a failed login, a successful login from a different time zone, a permission change followed by a download, duplicate events from two systems, and a missing log segment. Support preserves each source event and describes the gap without joining events into a narrative. The incident owner determines whether the records are related and what action follows. This separation lets offshore administrative support accelerate evidence assembly while preventing a chronology from becoming an accusation or notification decision.'}
  ], sources:researchSources }
];
const august18Slugs = new Set(august18ExplicitPosts.map(p => p.slug));
export const researchPosts: readonly ResearchPost[] = [...legacyResearchPosts.filter(p => !august18Slugs.has(p.slug)), ...august18ExplicitPosts];
